package deploy

import (
	"context"
	"fmt"
	"maps"
	"slices"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/interactive"
	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// resolveLocalConnectorBindings validates explicit choices and asks for any
// missing ones when terminal interaction is available. Choices are render
// inputs only: local rendering never persists them.
func resolveLocalConnectorBindings(ctx context.Context, opts manifestRunOptions, facts manifestFacts, lib *template.Library) (map[string]map[string]string, error) {
	fixtures, err := fixtureCatalog(lib)
	if err != nil {
		return nil, err
	}
	if len(fixtures) == 0 {
		return nil, fmt.Errorf("%s declares no fixture catalog (spec.local.fixtures on %s)\nuse --template-version to pin a library release that ships one", lib.Ref(), TemplateDeployComponent)
	}

	explicit, err := parseConnectorBindingArgs(opts.Bindings)
	if err != nil {
		return nil, err
	}
	connectors := make(map[string]ManifestConnector, len(facts.Model.Connectors))
	for _, connector := range facts.Model.Connectors {
		connectors[connector.Name] = connector
	}
	for _, name := range slices.Sorted(maps.Keys(explicit)) {
		fixture := explicit[name]
		if _, ok := connectors[name]; !ok {
			return nil, fmt.Errorf("--binding names connector %q, which the topology does not declare", name)
		}
		if !slices.Contains(fixtures, fixture) {
			return nil, fmt.Errorf("connector %s uses unsupported local fixture %q; available fixtures: %s", name, fixture, strings.Join(fixtures, ", "))
		}
	}

	resolved := make(map[string]map[string]string, len(facts.Model.Connectors))
	var missing []string
	for _, connector := range facts.Model.Connectors {
		fixture := explicit[connector.Name]
		if fixture == "" && opts.Selector != nil {
			fixture, err = selectConnectorBinding(ctx, opts.Selector, connector, fixtures)
			if err != nil {
				return nil, fmt.Errorf("select local binding for connector %s: %w", connector.Name, err)
			}
		}
		if fixture == "" {
			missing = append(missing, connector.Name)
			continue
		}
		if !slices.Contains(fixtures, fixture) {
			return nil, fmt.Errorf("connector %s uses unsupported local fixture %q; available fixtures: %s",
				connector.Name, fixture, strings.Join(fixtures, ", "))
		}
		resolved[connector.Name] = map[string]string{localEnv: fixture}
	}
	if len(missing) > 0 {
		return nil, fmt.Errorf("local bindings are required for connectors: %s\npass one '--binding <connector>=<fixture>' for each; available fixtures: %s",
			strings.Join(missing, ", "), strings.Join(fixtures, ", "))
	}
	return resolved, nil
}

func parseConnectorBindingArgs(args []string) (map[string]string, error) {
	bindings := make(map[string]string, len(args))
	for _, arg := range args {
		name, fixture, ok := strings.Cut(arg, "=")
		name, fixture = strings.TrimSpace(name), strings.TrimSpace(fixture)
		if !ok || name == "" || fixture == "" {
			return nil, fmt.Errorf("invalid --binding %q; use --binding <connector>=<fixture>", arg)
		}
		if _, duplicate := bindings[name]; duplicate {
			return nil, fmt.Errorf("--binding specifies connector %s more than once", name)
		}
		bindings[name] = fixture
	}
	return bindings, nil
}

func selectConnectorBinding(ctx context.Context, selector interactive.Selector, connector ManifestConnector, fixtures []string) (string, error) {
	options := make([]interactive.SelectOption, 0, len(fixtures))
	for _, fixture := range fixtures {
		options = append(options, interactive.SelectOption{
			Label: fixtureLabel(fixture),
			Value: fixture,
		})
	}
	return selector.Select(ctx, interactive.SelectRequest{
		Title:       "local binding for " + connector.Name,
		Description: connectorDescription(connector),
		Options:     options,
	})
}

func connectorDescription(connector ManifestConnector) string {
	var details []string
	if connector.ExternalSystem != "" {
		details = append(details, "external system "+connector.ExternalSystem)
	}
	if len(connector.AppIDs) > 0 {
		details = append(details, "used by "+strings.Join(connector.AppIDs, ", "))
	}
	if len(details) == 0 {
		return "choose the fixture this connector uses locally"
	}
	return strings.Join(details, "; ")
}

func fixtureLabel(fixture string) string {
	description := map[string]string{
		"blob": "S3 object store",
		"file": "local directory",
		"http": "HTTP stub",
		"sftp": "SFTP server",
		"smb":  "SMB share",
	}[fixture]
	if description == "" {
		return fixture
	}
	return fixture + " — " + description
}

// resolveGitOpsConnectorBindings records the developer's local fixture choices
// while leaving every deployable environment as a REPLACE-ME scaffold for the
// reviewer to complete.
func resolveGitOpsConnectorBindings(ctx context.Context, opts manifestRunOptions, facts manifestFacts, lib *template.Library) (map[string]map[string]string, error) {
	bindings, err := resolveLocalConnectorBindings(ctx, opts, facts, lib)
	if err != nil {
		return nil, err
	}
	for _, env := range facts.Environments {
		if env == localEnv {
			continue
		}
		for _, connector := range facts.Model.Connectors {
			fmt.Fprintf(opts.Stderr, "note: connector %s has no binding for %s; its manifests keep the REPLACE-ME scaffold\n", connector.Name, env)
		}
	}
	return bindings, nil
}

// fixtureCatalog reads the closed local fixture catalog from the fetched
// deploy-component template.
func fixtureCatalog(lib *template.Library) ([]string, error) {
	tmpl, _, err := lib.Open(TemplateDeployComponent)
	if err != nil {
		return nil, err
	}
	if tmpl.Spec.Local == nil {
		return nil, nil
	}
	return tmpl.Spec.Local.Fixtures, nil
}

// documented.
func seedDeclaredParams(tmpl *template.Template, seeds map[string]any) map[string]any {
	base := make(map[string]any, len(seeds))
	for _, f := range tmpl.Fields() {
		if v, ok := seeds[f.Name]; ok && !isBlank(v) {
			base[f.Name] = v
		}
	}
	return base
}

// isBlank drops an empty derived fact so the template's own default still
// applies: an unset platform.pubsub must not override `default: rabbitmq`.
func isBlank(v any) bool {
	s, ok := v.(string)
	return ok && s == ""
}

func (f manifestFacts) gitopsMap(component, env string) map[string]any {
	return map[string]any{
		"domain":             f.Domain,
		"system":             f.System,
		"component":          component,
		"env":                env,
		"host":               HostDirName,
		"registry":           f.Registry,
		"argocdAppNamespace": f.AppNamespace,
		"environments":       f.Environments,
		"platform": map[string]any{
			"provider":    f.Platform.Provider,
			"pubsub":      f.Platform.Pubsub,
			"secretStore": f.Platform.SecretStore,
		},
	}
}

// scaffoldValues is the component's recorded template values, or an empty map so
// a skeleton reading .scaffold.x never fails on a missing record.
func (f manifestFacts) scaffoldValues(component string) map[string]any {
	if s, ok := f.Scaffolds[component]; ok && s.Values != nil {
		return s.Values
	}
	return map[string]any{}
}

func toMap(v any) (map[string]any, error) {
	raw, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	var out map[string]any
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, err
	}
	return out, nil
}

type publishScaffoldOptions struct {
	StagingDir string
	Dest       *destTree
	Actions    []FileAction
	Rels       []string
	Branch     string
	Facts      manifestFacts
}

// publishedScaffold is what a successful push produced.
type publishedScaffold struct {
	Revision string

	// Placeholders are scanned from the working tree *while the branch is still
	// checked out*. Scanning afterwards would find nothing: restoring the default
	// branch takes the new files back out of the working tree.
	Placeholders []Placeholder
}

// publishScaffold writes the staged files on a fresh branch and pushes it.
//
// Never to the default branch: the tree is full of placeholders and unpinned
// images, and the ApplicationSet would generate Applications for it the moment it
// landed. A branch is the reviewable artefact.
//
// Publish is not reused: it is wired to a Plan and its rebase-retry loop is for a
// one-line contended edit. A fresh branch that is rejected already exists on the
// remote, which is a clear error rather than something to retry.
func publishScaffold(ctx context.Context, opts manifestRunOptions, repo *gitops.Repository, p publishScaffoldOptions) (publishedScaffold, error) {
	start := gitops.RemoteName + "/" + repo.Branch
	if err := repo.Git.CreateBranch(ctx, p.Branch, start); err != nil {
		return publishedScaffold{}, err
	}
	// Unconditionally, on success and on failure alike: the refresh on the next
	// Open resets whatever branch is current to the default branch's remote head,
	// so leaving the checkout here would silently discard these commits.
	defer func() {
		if err := repo.Git.Switch(ctx, repo.Branch); err != nil {
			fmt.Fprintf(opts.Stderr, "warning: could not restore %s in the cached checkout: %v\n", repo.Branch, err)
		}
	}()

	written, err := applyStaged(p.StagingDir, p.Dest, p.Actions)
	if err != nil {
		return publishedScaffold{}, err
	}
	// Only the paths staged, never `add -A`: the checkout is shared, and a
	// concurrent run's debris is not ours to commit.
	if err := repo.Git.Add(ctx, written...); err != nil {
		return publishedScaffold{}, err
	}
	// The scaffold is reviewed as a branch, and a reviewer reads the file list as
	// the whole of what this command did. It has to actually be that.
	if err := assertStagedIsExactly(ctx, repo.Git, written); err != nil {
		return publishedScaffold{}, err
	}
	subject := manifestCreateSubject(p.Facts, opts.reviewEnv, len(written))
	if err := repo.Git.Commit(ctx, subject, scaffoldTrailers(p.Facts, opts.reviewEnv, opts.CliVersion)); err != nil {
		return publishedScaffold{}, err
	}
	if err := assertCommittedIsExactly(ctx, repo.Git, written); err != nil {
		return publishedScaffold{}, err
	}
	if err := repo.Git.Push(ctx, gitops.RemoteName, "HEAD:refs/heads/"+p.Branch); err != nil {
		return publishedScaffold{}, fmt.Errorf("push %s: %w\n\nA rejection here usually means the branch already exists on the remote. Delete it, or merge the open review first.", p.Branch, err)
	}

	revision, err := repo.Git.HEAD(ctx)
	if err != nil {
		return publishedScaffold{}, err
	}
	// While the branch is still current — the deferred switch above takes these
	// files back out of the working tree.
	placeholders, err := scanPlaceholders(repo.Root, p.Rels)
	if err != nil {
		return publishedScaffold{}, err
	}
	return publishedScaffold{Revision: revision, Placeholders: placeholders}, nil
}

func manifestCreateSubject(facts manifestFacts, env string, files int) string {
	return fmt.Sprintf("manifests(%s): create %d %s file%s under %s", facts.System, files, env, plural(files), facts.Domain)
}

func scaffoldTrailers(facts manifestFacts, env, cliVersion string) string {
	trailers := []git.Trailer{
		{Key: TrailerDomain, Value: facts.Domain},
		{Key: TrailerSystem, Value: facts.System},
	}
	if env != "" {
		trailers = append(trailers, git.Trailer{Key: TrailerEnvironment, Value: env})
	}
	for _, c := range facts.Selected {
		trailers = append(trailers, git.Trailer{Key: TrailerComponent, Value: c.Name})
	}
	if who := committer(); who != "" {
		trailers = append(trailers, git.Trailer{Key: TrailerBy, Value: who})
	}
	if cliVersion != "" {
		trailers = append(trailers, git.Trailer{Key: TrailerCli, Value: cliVersion})
	}

	lines := make([]string, 0, len(trailers))
	for _, t := range trailers {
		lines = append(lines, t.String())
	}
	return strings.Join(lines, "\n")
}

// reportManifestCreate writes the action table, then what remains to be done.
func reportManifestCreate(out output, result ManifestCreateResult, actions []FileAction, planOnly bool) error {
	if out.Format == OutputJSON {
		enc := json.NewEncoder(out.Stdout)
		enc.SetIndent("", "  ")
		if err := enc.Encode(result); err != nil {
			return fmt.Errorf("write JSON result: %w", err)
		}
		return nil
	}

	for _, a := range actions {
		fmt.Fprintf(out.Stdout, "  %-12s %s\n", a.Action, a.Rel)
	}
	fmt.Fprintf(out.Stdout, "\n%s\n", summariseActions(actions))

	switch {
	case planOnly:
		fmt.Fprintln(out.Stdout, "nothing created (--dry-run)")
	case result.Applied:
		fmt.Fprintf(out.Stdout, "pushed branch %s at %s\n", result.Branch, git.ShortSHA(result.Revision))
	default:
		fmt.Fprintln(out.Stdout, "all manifest files already exist; nothing created")
	}

	reportPlaceholders(out, result.Placeholders)
	return nil
}

func conflictingPaths(actions []FileAction) []string {
	var out []string
	for _, a := range actions {
		if a.Action == ActionConflict {
			out = append(out, a.Rel)
		}
	}
	return out
}

func refuseManifestReplacements(actions []FileAction) error {
	conflicts := conflictingPaths(actions)
	if len(conflicts) == 0 {
		return nil
	}
	var lines []string
	for _, rel := range conflicts {
		lines = append(lines, "  "+rel)
	}
	return fmt.Errorf("%d manifest file%s already exist and differ:\n%s\nmanifests create never replaces files; edit the existing GitOps files or remove them before creating again",
		len(conflicts), plural(len(conflicts)), strings.Join(lines, "\n"))
}

func reportManifestCreateDiff(w io.Writer, staging string, dest *destTree, actions []FileAction) error {
	for _, action := range actions {
		if action.Action == ActionIdentical {
			continue
		}
		after, err := os.ReadFile(filepath.Join(staging, filepath.FromSlash(action.Rel)))
		if err != nil {
			return fmt.Errorf("read staged %s: %w", action.Rel, err)
		}
		before, err := dest.read(action.Rel)
		if err != nil && !errors.Is(err, fs.ErrNotExist) {
			return fmt.Errorf("read %s: %w", action.Rel, err)
		}
		diff := kustomize.Diff(before, after, action.Rel+" (current)", action.Rel+" (generated)", kustomize.PlainPalette)
		if diff != "" {
			fmt.Fprint(w, diff)
		}
	}
	return nil
}

apiVersion: intropy.dev/v1
kind: Template
metadata:
  name: deploy-host
  title: System deployment manifests (shared)
  description: The Dapr components, secret store and secrets a system's blocks share, as one ArgoCD Application.
  tags: [deploy, gitops, kustomize, dapr]
  labels:
    intropy.dev/template-kind: deploy
spec:
  parameters:
    type: object
    required: [domain, system, namespace]
    properties:
      domain:
        type: string
        title: Domain
        description: Business domain the system belongs to, as a GitOps path segment.
        pattern: "^[a-z][a-z0-9-]*$"
      system:
        type: string
        title: System
        description: System name, as a GitOps path segment.
        pattern: "^[a-z][a-z0-9-]*$"
      namespace:
        type: string
        title: Namespace
        description: The Kubernetes namespace the system's blocks run in. With namespacePerEnv the environment is prefixed to it.
        default: integrations
        pattern: "^[a-z][a-z0-9-]*$"
      namespacePerEnv:
        type: boolean
        title: Namespace per environment
        description: Prefix the environment to the namespace, e.g. test-acme-integrations. Leave false for a single flat namespace.
        default: false
      pubsub:
        type: string
        title: Pub/sub broker
        description: The Dapr pub/sub building block to declare, from deploy.yaml platform.pubsub.
        enum: [in-memory, rabbitmq, servicebus]
        default: rabbitmq
      pubsubName:
        type: string
        title: Pub/sub component name
        description: The name blocks resolve the broker by. Must match what the generated C# uses.
        default: pubsub
        pattern: "^[a-z][a-z0-9-]*$"
      secretStore:
        type: string
        title: Secret store
        description: Where credentials come from. Only "kubernetes" commits a Secret stub; the others resolve out of cluster.
        enum: [kubernetes, azure-keyvault, vault]
        default: kubernetes
  values:
    secretName: "{{ .system }}-secrets"

  # Which files exist at all, rather than only what is in them. First match
  # decides; a path no rule matches is always included.
  files:
    - path: base/dapr/pubsub-in-memory.yaml.tmpl
      when: '{{ eq .pubsub "in-memory" }}'
    - path: base/dapr/pubsub-rabbitmq.yaml.tmpl
      when: '{{ eq .pubsub "rabbitmq" }}'
    - path: base/dapr/pubsub-servicebus.yaml.tmpl
      when: '{{ eq .pubsub "servicebus" }}'

    - path: base/dapr/secretstore-kubernetes.yaml.tmpl
      when: '{{ eq .secretStore "kubernetes" }}'
    - path: base/dapr/secretstore-azure-keyvault.yaml.tmpl
      when: '{{ eq .secretStore "azure-keyvault" }}'
    - path: base/dapr/secretstore-vault.yaml.tmpl
      when: '{{ eq .secretStore "vault" }}'

    # An in-cluster Secret only makes sense when the secret store reads from the
    # cluster. With Key Vault or Vault the values live there and committing a
    # placeholder Secret would be misleading.
    - path: base/secrets/**
      when: '{{ eq .secretStore "kubernetes" }}'

    # No external connectors means no bindings, and an empty multi-doc file in a
    # kustomize resources list breaks the build.
    - path: base/bindings/**
      when: '{{ gt (len .topology.connectors) 0 }}'

