-- deploy component catalog --
apiVersion: intropy.dev/v1
kind: Template
metadata:
  name: deploy-component
  title: Block deployment manifests
  description: The workload and overlays for one block, as one ArgoCD Application.
  tags: [deploy, gitops, kustomize]
  labels:
    intropy.dev/template-kind: deploy
spec:
  parameters:
    type: object
    # domain is optional, deliberately: it is only a GitOps path segment, no
    # skeleton references it, and a local render has no domain. GitOps creation
    # derives it from the destination or requires --domain.
    required: [name, system, registry]
    properties:
      name:
        type: string
        title: Component
        description: Block name, as a GitOps path segment.
        pattern: "^[a-z][a-z0-9-]*$"
      domain:
        type: string
        title: Domain
        description: Only a GitOps path segment; no skeleton file references it.
        pattern: "^[a-z][a-z0-9-]*$"
      system:
        type: string
        title: System
        pattern: "^[a-z][a-z0-9-]*$"
      appId:
        type: string
        title: Dapr app-id
        description: The identity the sidecar registers as, and what a Component's scopes list.
      kind:
        type: string
        title: Block kind
        description: The topology's block kind, carried through as a label.
        default: ""
      workload:
        type: string
        title: Workload
        description: An extractor is scheduled and exits; everything else stays resident.
        enum: [cronjob, deployment]
        default: deployment
      registry:
        type: string
        title: Registry
        description: The registry from deploy.yaml.
      imageNamespace:
        type: string
        title: Image namespace
        description: The path segment between the registry and the image name. Must match what CI pushes.
        default: integrations
      replicas:
        type: integer
        title: Replicas
        default: 1
      sourceDir:
        type: string
        title: Source directory
        description: The block's directory in the source repository, used for component.yaml sourcePaths. Empty when no scaffold record was found.
        default: ""
  # The closed fixture catalog for the local development cluster: one Dapr
  # binding skeleton per fixture type in overlays/local/fixtures/, switched on
  # the connector's binding for this render. Local manifest rendering fails a
  # release that ships a local overlay without this list and validates explicit
  # or interactive choices against it. Adding a fixture is a skeleton file, an
  # entry here, and the fixture server in the k3s setup scripts — a template PR,
  # not a CLI release.
  local:
    fixtures: [sftp, smb, http, file, blob]

  values:
    imageRepo: "{{ .registry }}/{{ .imageNamespace }}/{{ .name }}"
    # The tag CI pushes on every build, so a rendered environment runs the
    # freshest component image. `intropy deploy pin` writes the digest when a
    # deployment must be frozen.
    imageTag: "dev"

  files:
    # The CronJob's schedule is deployment configuration that differs between
    # the local cluster (a dev cadence, applied unreviewed) and every other
    # environment (a REPLACE-ME a human fills in), and .env may only vary
    # under overlays/ — so the variant is picked here, per file, and
    # base/kustomization.yaml names the picked file. First match decides.
    - path: base/cronjob.yaml.tmpl
      when: '{{ and (eq .workload "cronjob") (ne .env "local") }}'
    - path: base/cronjob-local.yaml.tmpl
      when: '{{ and (eq .workload "cronjob") (eq .env "local") }}'
    - path: base/deployment.yaml.tmpl
      when: '{{ eq .workload "deployment" }}'

    # The local overlay is static rather than named by .env, so its files must
    # only render during the local pass. A fixture file exists only when one
    # connector selected it; otherwise the kustomization must not reference it.
    - path: overlays/local/kustomization.yaml.tmpl
      when: '{{ eq .env "local" }}'
    - path: overlays/local/fixtures/sftp.yaml.tmpl
      when: '{{- $recorded := dig "local" "bindings" dict . -}}{{- range .topology.connectors }}{{- $binding := default (get $recorded .name) (dig "binding" "" .) -}}{{- if eq $binding "sftp" }}true{{- end }}{{- end }}'
    - path: overlays/local/fixtures/smb.yaml.tmpl
      when: '{{- $recorded := dig "local" "bindings" dict . -}}{{- range .topology.connectors }}{{- $binding := default (get $recorded .name) (dig "binding" "" .) -}}{{- if eq $binding "smb" }}true{{- end }}{{- end }}'
    - path: overlays/local/fixtures/http.yaml.tmpl
      when: '{{- $recorded := dig "local" "bindings" dict . -}}{{- range .topology.connectors }}{{- $binding := default (get $recorded .name) (dig "binding" "" .) -}}{{- if eq $binding "http" }}true{{- end }}{{- end }}'
    - path: overlays/local/fixtures/file.yaml.tmpl
      when: '{{- $recorded := dig "local" "bindings" dict . -}}{{- range .topology.connectors }}{{- $binding := default (get $recorded .name) (dig "binding" "" .) -}}{{- if eq $binding "file" }}true{{- end }}{{- end }}'
    - path: overlays/local/fixtures/blob.yaml.tmpl
      when: '{{- $recorded := dig "local" "bindings" dict . -}}{{- range .topology.connectors }}{{- $binding := default (get $recorded .name) (dig "binding" "" .) -}}{{- if eq $binding "blob" }}true{{- end }}{{- end }}'

    # The generic environment overlay never renders for the local environment:
    # it and overlays/local/ would both land at overlays/local/, and the walk
    # order ("local" sorts before "{{ .env }}") means the thin overlay would
    # silently overwrite the fixture-carrying one. local is reserved for the
    # local overlay — no customer environment may be named that.
    - path: 'overlays/{{ .env }}/**'
      when: '{{ ne .env "local" }}'

-- current branch host bindings --
# One Dapr binding per connector the topology declares, as a multi-document file.
#
# Multi-doc rather than a file each: kustomize reads it natively, and adding a
# connector stays a one-file diff. The topology mints only the connector's name
# and scopes. Binding type, address, and credentials are environment-owned
# GitOps configuration, so create-only onboarding leaves explicit placeholders
# for the reviewer. The name must not change: blocks resolve the binding as
# binding.<connector-name>.
{{- range .topology.connectors }}
---
apiVersion: dapr.io/v1alpha1
kind: Component
metadata:
  name: {{ .name }}
spec:
  # Pick the Dapr binding this connector deploys as (for example,
  # bindings.sftp or bindings.http) and fill in its metadata below.
  type: REPLACE-ME-BINDING-TYPE
  version: v1
  metadata:
    - name: REPLACE-ME-METADATA-NAME
      value: REPLACE-ME-METADATA-VALUE
scopes:
{{- range .appIds }}
  - {{ . }}
{{- end }}
{{- end }}

-- manifest model --
package deploy

import (
	"encoding/json"
	"fmt"
	"maps"
	"path/filepath"
	"slices"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// The Kubernetes workload a block runs as.
//
// An extractor is scheduled: it wakes, pulls from its source and exits, which is
// a CronJob. Every other block reacts to messages or requests and must stay
// resident. This is what the hand-written customer repos already do — fluxia and
// entrovia both run their extractors as CronJobs — so deriving it from the
// topology is reproducing an existing convention, not inventing one.
const (
	WorkloadCronJob    = "cronjob"
	WorkloadDeployment = "deployment"
)

// blockKindExtractor is the topology's block kind for a scheduled extractor.
// Records spell kinds inconsistently (camelCase from one emitter, kebab-case
// after the frontend normalises), so the comparison folds case.
const blockKindExtractor = "extractor"

// ManifestModel is the topology view a manifest skeleton sees under the reserved
// "topology" key: derived, flattened and sorted.
//
// Raw topology.Topology is unsuitable for two reasons. Its APIs, Provides and
// Consumes are json.RawMessage whose element shape is not finalised, so a
// skeleton ranging over them would break when it is. And neither Go map
// iteration nor host emission order is stable, while repeatable rendering
// depends on a re-render being byte-identical — so everything here is sorted.
type ManifestModel struct {
	System     string              `json:"system"`
	Components []ManifestComponent `json:"components"`
	PubSubs    []ManifestPubSub    `json:"pubsubs"`
	Topics     []ManifestTopic     `json:"topics"`
	Connectors []ManifestConnector `json:"connectors"`
}

// ManifestComponent is one block as the manifests need it.
type ManifestComponent struct {
	// Name is the topology component name, which is also the GitOps component
	// directory segment.
	Name string `json:"name"`

	// Kind is the topology block kind, carried through verbatim for labels.
	Kind string `json:"kind"`

	// AppID is the Dapr app-id: what a Component's scopes list and what the
	// generated C# resolves components by. Falls back to Name when no scaffold
	// record declares one.
	AppID string `json:"appId"`

	// Workload is WorkloadCronJob or WorkloadDeployment.
	Workload string `json:"workload"`

	// Dir is the component's source directory relative to the system root, when
	// a scaffold record was matched. Empty otherwise — a missing record is a
	// warning, not a failure, so the manifests still generate.
	Dir string `json:"dir,omitempty"`

	Topics     []string `json:"topics,omitempty"`
	Connectors []string `json:"connectors,omitempty"`
}

// ManifestPubSub is one Dapr pub/sub component the system needs.
type ManifestPubSub struct {
	Name   string   `json:"name"`
	Topics []string `json:"topics,omitempty"`

	// AppIDs is what belongs in the Component's scopes: every app-id the
	// topology says publishes to or subscribes from one of its topics.
	AppIDs []string `json:"appIds,omitempty"`
}

// ManifestTopic is a declared topic, with the ends resolved to app-ids.
type ManifestTopic struct {
	PubSub      string   `json:"pubsub"`
	Topic       string   `json:"topic"`
	Contract    string   `json:"contract,omitempty"`
	Publishers  []string `json:"publishers,omitempty"`
	Subscribers []string `json:"subscribers,omitempty"`
}

// ManifestConnector is an external integration point. The topology mints only
// its name: the deployed Dapr binding's address, host and credentials are
// environment-owned deployment configuration, which is exactly why they are
// placeholders in the rendered manifests.
type ManifestConnector struct {
	Name           string   `json:"name"`
	ExternalSystem string   `json:"externalSystem,omitempty"`
	Directions     []string `json:"directions,omitempty"`
	AppIDs         []string `json:"appIds,omitempty"`

	// Binding is the fixture selected for this local render. GitOps creation
	// leaves it empty so the generated source keeps its placeholder scaffold.
	Binding string `json:"binding,omitempty"`
}

// newManifestModel derives the model from a decoded topology record and whatever
// scaffold records were found in the workspace.
func newManifestModel(t *topology.Topology, scaffolds []template.ScaffoldEntry) ManifestModel {
	appIDs, dirs := joinScaffolds(t.Components, matchScaffolds(t.Components, scaffolds))

	m := ManifestModel{System: t.System}
	m.Components = buildComponents(t.Components, appIDs, dirs)
	m.Topics = buildTopics(t.Topics, appIDs)
	m.PubSubs = buildPubSubs(t, appIDs)
	m.Connectors = buildConnectors(t.Connectors, appIDs)
	return m
}

// asMap renders the model as plain maps and slices, with each connector's
// binding set for the environment being rendered.
//
// Injected reserved values go through this so a skeleton's `index`, `range` and
// sprig calls see uniform map[string]any — a Go struct behaves differently
// under `index` and would make the template author's life needlessly subtle.
func (m ManifestModel) asMap(env string, bindings map[string]map[string]string) (map[string]any, error) {
	for i, c := range m.Connectors {
		m.Connectors[i].Binding = bindings[c.Name][env]
	}
	raw, err := json.Marshal(m)
	if err != nil {
		return nil, fmt.Errorf("encode topology model: %w", err)
	}
	var out map[string]any
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, fmt.Errorf("decode topology model: %w", err)
	}
	return out, nil
}

// bindingsForEnv reduces this render's choices to a flat connector-to-binding
// map for compatibility with older local fixture templates.
func bindingsForEnv(model ManifestModel, bindings map[string]map[string]string, env string) map[string]string {
	out := make(map[string]string, len(model.Connectors))
	for _, c := range model.Connectors {
		if b := bindings[c.Name][env]; b != "" {
			out[c.Name] = b
		}
	}
	return out
}

// matchScaffolds pairs each topology component with its scaffold record.
//
// The join is by convention, and the toolchain uses two conventions: a
// component's directory basename, and its scaffold record's values.appId. Both
// are matched — directory first — because a record found by either is better
// than manifests generated without one. A component with no record is simply
// absent from the result: that is a warning, not a failure.
func matchScaffolds(components []topology.Component, scaffolds []template.ScaffoldEntry) map[string]template.ScaffoldEntry {
	byDir := make(map[string]template.ScaffoldEntry, len(scaffolds))
	byAppID := make(map[string]template.ScaffoldEntry, len(scaffolds))
	for _, s := range scaffolds {
		byDir[filepath.Base(s.Path)] = s
		if id := scaffoldString(s, "appId"); id != "" {
			byAppID[id] = s
		}
	}

	out := make(map[string]template.ScaffoldEntry, len(components))
	for _, c := range components {
		if match, found := byDir[c.Name]; found {
			out[c.Name] = match
			continue
		}
		if match, found := byAppID[c.Name]; found {
			out[c.Name] = match
		}
	}
	return out
}

// joinScaffolds reduces the matched records to the two facts the model needs.
func joinScaffolds(components []topology.Component, matched map[string]template.ScaffoldEntry) (appIDs, dirs map[string]string) {
	appIDs = make(map[string]string, len(components))
	dirs = make(map[string]string, len(components))
	for _, c := range components {
		match, found := matched[c.Name]
		if !found {
			continue
		}
		dirs[c.Name] = filepath.Base(match.Path)
		if id := scaffoldString(match, "appId"); id != "" {
			appIDs[c.Name] = id
		}
	}
	return appIDs, dirs
}

func scaffoldString(s template.ScaffoldEntry, key string) string {
	v, _ := s.Values[key].(string)
	return v
}

// appIDOf resolves a component name to an app-id.
//
// A name with no entry is returned unchanged. That covers two cases: a component
// with no scaffold record, and a name that is not a component of this system at
// all — Topic.Publishers and Topic.Subscribers may reference a block deployed
// elsewhere, and denying it access to the broker would be worse than scoping a
// name we cannot resolve.
func appIDOf(appIDs map[string]string, name string) string {
	if id, ok := appIDs[name]; ok {
		return id
	}
	return name
}

func buildComponents(components []topology.Component, appIDs, dirs map[string]string) []ManifestComponent {
	out := make([]ManifestComponent, 0, len(components))
	for _, c := range components {
		ic := ManifestComponent{
			Name:     c.Name,
			Kind:     c.Kind,
			AppID:    appIDOf(appIDs, c.Name),
			Workload: workloadFor(c.Kind),
			Dir:      dirs[c.Name],
		}

		topics := map[string]bool{}
		for _, s := range c.Subscribes {
			topics[s.Topic] = true
		}
		for _, p := range c.Publishes {
			topics[p.Topic] = true
		}
		ic.Topics = sortedKeys(topics)

		conns := map[string]bool{}
		for _, u := range c.Connectors {
			conns[u.Connector] = true
		}
		ic.Connectors = sortedKeys(conns)

		out = append(out, ic)
	}
	slices.SortFunc(out, func(a, b ManifestComponent) int { return strings.Compare(a.Name, b.Name) })
	return out
}

// workloadFor maps a block kind to its Kubernetes workload. Anything that is not
// an extractor stays resident, which is the safe default: a block wrongly run as
// a CronJob would silently stop consuming.
func workloadFor(kind string) string {
	if strings.EqualFold(kind, blockKindExtractor) {
		return WorkloadCronJob
	}
	return WorkloadDeployment
}

func buildTopics(topics []topology.Topic, appIDs map[string]string) []ManifestTopic {
	out := make([]ManifestTopic, 0, len(topics))
	for _, t := range topics {
		out = append(out, ManifestTopic{
			PubSub:      t.PubSub,
			Topic:       t.Topic,
			Contract:    t.Contract,
			Publishers:  sortedAppIDs(appIDs, t.Publishers),
			Subscribers: sortedAppIDs(appIDs, t.Subscribers),
		})
	}
	slices.SortFunc(out, func(a, b ManifestTopic) int {
		if c := strings.Compare(a.PubSub, b.PubSub); c != 0 {
			return c
		}
		return strings.Compare(a.Topic, b.Topic)
	})
	return out
}

package deploy

import (
	"context"
	"fmt"
	"maps"
	"slices"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/interactive"
	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// resolveLocalConnectorBindings validates explicit choices and asks for any
// missing ones when terminal interaction is available. Choices are render
// inputs only: local rendering never persists them.
func resolveLocalConnectorBindings(ctx context.Context, opts manifestRunOptions, facts manifestFacts, lib *template.Library) (map[string]map[string]string, error) {
	fixtures, err := fixtureCatalog(lib)
	if err != nil {
		return nil, err
	}
	if len(fixtures) == 0 {
		return nil, fmt.Errorf("%s declares no fixture catalog (spec.local.fixtures on %s)\nuse --template-version to pin a library release that ships one", lib.Ref(), TemplateDeployComponent)
	}

	explicit, err := parseConnectorBindingArgs(opts.Bindings)
	if err != nil {
		return nil, err
	}
	connectors := make(map[string]ManifestConnector, len(facts.Model.Connectors))
	for _, connector := range facts.Model.Connectors {
		connectors[connector.Name] = connector
	}
	for _, name := range slices.Sorted(maps.Keys(explicit)) {
		fixture := explicit[name]
		if _, ok := connectors[name]; !ok {
			return nil, fmt.Errorf("--binding names connector %q, which the topology does not declare", name)
		}
		if !slices.Contains(fixtures, fixture) {
			return nil, fmt.Errorf("connector %s uses unsupported local fixture %q; available fixtures: %s", name, fixture, strings.Join(fixtures, ", "))
		}
	}

	resolved := make(map[string]map[string]string, len(facts.Model.Connectors))
	var missing []string
	for _, connector := range facts.Model.Connectors {
		fixture := explicit[connector.Name]
		if fixture == "" && opts.Selector != nil {
			fixture, err = selectConnectorBinding(ctx, opts.Selector, connector, fixtures)
			if err != nil {
				return nil, fmt.Errorf("select local binding for connector %s: %w", connector.Name, err)
			}
		}
		if fixture == "" {
			missing = append(missing, connector.Name)
			continue
		}
		if !slices.Contains(fixtures, fixture) {
			return nil, fmt.Errorf("connector %s uses unsupported local fixture %q; available fixtures: %s",
				connector.Name, fixture, strings.Join(fixtures, ", "))
		}
		resolved[connector.Name] = map[string]string{localEnv: fixture}
	}
	if len(missing) > 0 {
		return nil, fmt.Errorf("local bindings are required for connectors: %s\npass one '--binding <connector>=<fixture>' for each; available fixtures: %s",
			strings.Join(missing, ", "), strings.Join(fixtures, ", "))
	}
	return resolved, nil
}

func parseConnectorBindingArgs(args []string) (map[string]string, error) {
	bindings := make(map[string]string, len(args))
	for _, arg := range args {
		name, fixture, ok := strings.Cut(arg, "=")
		name, fixture = strings.TrimSpace(name), strings.TrimSpace(fixture)
		if !ok || name == "" || fixture == "" {
			return nil, fmt.Errorf("invalid --binding %q; use --binding <connector>=<fixture>", arg)
		}
		if _, duplicate := bindings[name]; duplicate {
			return nil, fmt.Errorf("--binding specifies connector %s more than once", name)
		}
		bindings[name] = fixture
	}
	return bindings, nil
}

func selectConnectorBinding(ctx context.Context, selector interactive.Selector, connector ManifestConnector, fixtures []string) (string, error) {
	options := make([]interactive.SelectOption, 0, len(fixtures))
	for _, fixture := range fixtures {
		options = append(options, interactive.SelectOption{
			Label: fixtureLabel(fixture),
			Value: fixture,
		})
	}
	return selector.Select(ctx, interactive.SelectRequest{
		Title:       "local binding for " + connector.Name,
		Description: connectorDescription(connector),
		Options:     options,
	})
}

func connectorDescription(connector ManifestConnector) string {
	var details []string
	if connector.ExternalSystem != "" {
		details = append(details, "external system "+connector.ExternalSystem)
	}
	if len(connector.AppIDs) > 0 {
		details = append(details, "used by "+strings.Join(connector.AppIDs, ", "))
	}
	if len(details) == 0 {
		return "choose the fixture this connector uses locally"
	}
	return strings.Join(details, "; ")
}

func fixtureLabel(fixture string) string {
	description := map[string]string{
		"blob": "S3 object store",
		"file": "local directory",
		"http": "HTTP stub",
		"sftp": "SFTP server",
		"smb":  "SMB share",
	}[fixture]
	if description == "" {
		return fixture
	}
	return fixture + " — " + description
}

// emptyGitOpsBindings leaves connector types unset for reviewers to complete
// in the GitOps repository. Local fixture choices belong solely to render.
func emptyGitOpsBindings(opts manifestRunOptions, facts manifestFacts) map[string]map[string]string {
	for _, env := range facts.Environments {
		for _, connector := range facts.Model.Connectors {
			fmt.Fprintf(opts.Stderr, "note: connector %s has no binding for %s; its manifests keep the REPLACE-ME scaffold\n", connector.Name, env)
		}
	}
	return map[string]map[string]string{}
}

// fixtureCatalog reads the closed local fixture catalog from the fetched
// deploy-component template.
func fixtureCatalog(lib *template.Library) ([]string, error) {
	tmpl, _, err := lib.Open(TemplateDeployComponent)
	if err != nil {
		return nil, err
	}
	if tmpl.Spec.Local == nil {
		return nil, nil
	}
	return tmpl.Spec.Local.Fixtures, nil
}

