// resolveLocalConnectorBindings maps one render's fixture choices to the local
// environment. They are never persisted outside that render.
func resolveLocalConnectorBindings(ctx context.Context, opts manifestRunOptions, facts manifestFacts, lib *template.Library) (map[string]map[string]string, error) {
	choices, err := resolveConnectorBindingChoices(ctx, opts, facts, lib, "local")
	if err != nil {
		return nil, err
	}
	return bindChoicesToEnvironments(choices, []string{localEnv}), nil
}

// resolveGitOpsConnectorBindings maps binding choices to every GitOps
// environment rendered by create. Local rendering resolves its own choices,
// so the two commands cannot affect one another.
func resolveGitOpsConnectorBindings(ctx context.Context, opts manifestRunOptions, facts manifestFacts, lib *template.Library) (map[string]map[string]string, error) {
	choices, err := resolveConnectorBindingChoices(ctx, opts, facts, lib, "GitOps")
	if err != nil {
		return nil, err
	}
	return bindChoicesToEnvironments(choices, facts.Environments), nil
}

// resolveConnectorBindingChoices validates explicit kinds and asks for the
// missing ones. The catalog defines binding kinds for both local and GitOps
// rendering; only the target environment map differs between the callers.
func resolveConnectorBindingChoices(ctx context.Context, opts manifestRunOptions, facts manifestFacts, lib *template.Library, target string) (map[string]string, error) {
	fixtures, err := fixtureCatalog(lib)
	if err != nil {
		return nil, err
	}
	if len(fixtures) == 0 {
		return nil, fmt.Errorf("%s declares no binding catalog (spec.local.fixtures on %s)\nuse --template-version to pin a library release that ships one", lib.Ref(), TemplateDeployComponent)
	}

	explicit, err := parseConnectorBindingArgs(opts.Bindings)
	if err != nil {
		return nil, err
	}
	connectors := make(map[string]ManifestConnector, len(facts.Model.Connectors))
	for _, connector := range facts.Model.Connectors {
		connectors[connector.Name] = connector
	}
	for _, name := range slices.Sorted(maps.Keys(explicit)) {
		binding := explicit[name]
		if _, ok := connectors[name]; !ok {
			return nil, fmt.Errorf("--binding names connector %q, which the topology does not declare", name)
		}
		if !slices.Contains(fixtures, binding) {
			return nil, fmt.Errorf("connector %s uses unsupported binding kind %q; available kinds: %s", name, binding, strings.Join(fixtures, ", "))
		}
	}

	choices := make(map[string]string, len(facts.Model.Connectors))
	var missing []string
	for _, connector := range facts.Model.Connectors {
		binding := explicit[connector.Name]
		if binding == "" && opts.Selector != nil {
			binding, err = selectConnectorBinding(ctx, opts.Selector, connector, fixtures, target)
			if err != nil {
				return nil, fmt.Errorf("select %s binding for connector %s: %w", strings.ToLower(target), connector.Name, err)
			}
		}
		if binding == "" {
			missing = append(missing, connector.Name)
			continue
		}
		if !slices.Contains(fixtures, binding) {
			return nil, fmt.Errorf("connector %s uses unsupported binding kind %q; available kinds: %s",
				connector.Name, binding, strings.Join(fixtures, ", "))
		}
		choices[connector.Name] = binding
	}
	if len(missing) > 0 {
		return nil, fmt.Errorf("%s bindings are required for connectors: %s\npass one '--binding <connector>=<kind>' for each; available kinds: %s",
			strings.ToLower(target), strings.Join(missing, ", "), strings.Join(fixtures, ", "))
	}
	return choices, nil
}

func bindChoicesToEnvironments(choices map[string]string, environments []string) map[string]map[string]string {
	resolved := make(map[string]map[string]string, len(choices))
	for connector, binding := range choices {
		perEnvironment := make(map[string]string, len(environments))
		for _, environment := range environments {
			perEnvironment[environment] = binding
		}
		resolved[connector] = perEnvironment
	}
	return resolved
}

