// Package interactive provides terminal interaction behind small interfaces so
// commands can keep non-interactive behavior explicit and testable.
package interactive

import (
	"context"
	"io"
	"os"

	"charm.land/huh/v2"
	"golang.org/x/term"
)

// SelectOption is one value shown by a Selector.
type SelectOption struct {
	Label string
	Value string
}

// SelectRequest describes one terminal selection.
type SelectRequest struct {
	Title       string
	Description string
	Options     []SelectOption
}

// Selector chooses one value from a closed list.
type Selector interface {
	Select(context.Context, SelectRequest) (string, error)
}

// HuhSelector presents selections with Huh and keeps its terminal UI off
// stdout, which remains available for command results.
type HuhSelector struct {
	input  io.Reader
	output io.Writer
}

// NewTerminalSelector returns a Huh selector when both input and output are
// terminals. A nil result tells the caller to use its non-interactive path.
func NewTerminalSelector(input io.Reader, output io.Writer) Selector {
	in, inputIsFile := input.(*os.File)
	out, outputIsFile := output.(*os.File)
	if !inputIsFile || !outputIsFile || !term.IsTerminal(int(in.Fd())) || !term.IsTerminal(int(out.Fd())) {
		return nil
	}
	return &HuhSelector{input: input, output: output}
}

// Select presents one Huh select field and returns its selected value.
func (s *HuhSelector) Select(ctx context.Context, req SelectRequest) (string, error) {
	options := make([]huh.Option[string], 0, len(req.Options))
	for _, option := range req.Options {
		options = append(options, huh.NewOption(option.Label, option.Value))
	}

	var selected string
	field := huh.NewSelect[string]().
		Title(req.Title).
		Description(req.Description).
		Options(options...).
		Value(&selected)
	form := huh.NewForm(huh.NewGroup(field)).
		WithInput(s.input).
		WithOutput(s.output).
		WithAccessible(os.Getenv("ACCESSIBLE") != "")
	if err := form.RunWithContext(ctx); err != nil {
		return "", err
	}
	return selected, nil
}

func (t *Template) validate() error {
	if t.APIVersion != APIVersionV1 {
		return fmt.Errorf("unsupported apiVersion %q (want %q)", t.APIVersion, APIVersionV1)
	}
	if t.Kind != KindTemplate {
		return fmt.Errorf("unsupported kind %q (want %q)", t.Kind, KindTemplate)
	}
	if t.Metadata.Name == "" {
		return fmt.Errorf("metadata.name is required")
	}
	if t.Spec.Parameters == nil {
		return fmt.Errorf("spec.parameters is required")
	}
	if typ, _ := t.Spec.Parameters["type"].(string); typ != "object" {
		return fmt.Errorf(`spec.parameters.type must be "object"`)
	}
	for i, rule := range t.Spec.Files {
		if rule.Path == "" {
			return fmt.Errorf("spec.files[%d]: path is required", i)
		}
		// A rule with no condition either does nothing or means the author
		// forgot the condition; neither deserves to render.
		if rule.When == "" {
			return fmt.Errorf("spec.files[%d] (%s): when is required", i, rule.Path)
		}
		// Parsed here so a syntax error surfaces at load time rather than
		// partway through a render.
		if _, err := compileExpr(rule.When); err != nil {
			return fmt.Errorf("spec.files[%d] (%s): invalid when: %w", i, rule.Path, err)
		}
	}
	for i, dep := range t.Spec.Dependencies {
		if err := validateTemplateName(dep.Template); err != nil {
			return fmt.Errorf("spec.dependencies[%d]: %w", i, err)
		}
		if dep.Output == "" {
			return fmt.Errorf("spec.dependencies[%d] (%s): output is required", i, dep.Template)
		}
	}
	if t.Spec.Local != nil {
		seen := make(map[string]bool, len(t.Spec.Local.Fixtures))
		for i, fx := range t.Spec.Local.Fixtures {
			if !fixtureNamePattern.MatchString(fx) {
				return fmt.Errorf("spec.local.fixtures[%d]: %q is not a valid fixture name (lowercase letters, digits and dashes, starting with a letter or digit)", i, fx)
			}
			if seen[fx] {
				return fmt.Errorf("spec.local.fixtures[%d]: %q is declared twice", i, fx)
			}
			seen[fx] = true
		}
	}
	return nil
}

