// resolveLocalConnectorBindings maps one render's fixture choices to the local
// environment. They are never persisted outside that render.
func resolveLocalConnectorBindings(ctx context.Context, opts manifestRunOptions, facts manifestFacts, lib *template.Library) (map[string]map[string]string, error) {
	choices, err := resolveConnectorBindingChoices(ctx, opts, facts, lib, "local")
	if err != nil {
		return nil, err
	}
	return bindChoicesToEnvironments(choices, []string{localEnv}), nil
}

// resolveGitOpsConnectorBindings maps binding choices to every GitOps
// environment rendered by create. Local rendering resolves its own choices,
// so the two commands cannot affect one another.
func resolveGitOpsConnectorBindings(ctx context.Context, opts manifestRunOptions, facts manifestFacts, lib *template.Library) (map[string]map[string]string, error) {
	choices, err := resolveConnectorBindingChoices(ctx, opts, facts, lib, "GitOps")
	if err != nil {
		return nil, err
	}
	return bindChoicesToEnvironments(choices, facts.Environments), nil
}

// resolveConnectorBindingChoices validates explicit kinds and asks for the
// missing ones. The catalog defines binding kinds for both local and GitOps
// rendering; only the target environment map differs between the callers.
func resolveConnectorBindingChoices(ctx context.Context, opts manifestRunOptions, facts manifestFacts, lib *template.Library, target string) (map[string]string, error) {
	fixtures, err := fixtureCatalog(lib)
	if err != nil {
		return nil, err
	}
	valueLabel, catalogLabel := "kind", "binding catalog"
	if target == "local" {
		valueLabel, catalogLabel = "fixture", "fixture catalog"
	}
	if len(fixtures) == 0 {
		return nil, fmt.Errorf("%s declares no %s (spec.local.fixtures on %s)\nuse --template-version to pin a library release that ships one", lib.Ref(), catalogLabel, TemplateDeployComponent)
	}

	explicit, err := parseConnectorBindingArgs(opts.Bindings)
	if err != nil {
		return nil, err
	}
	connectors := make(map[string]ManifestConnector, len(facts.Model.Connectors))
	for _, connector := range facts.Model.Connectors {
		connectors[connector.Name] = connector
	}
	for _, name := range slices.Sorted(maps.Keys(explicit)) {
		binding := explicit[name]
		if _, ok := connectors[name]; !ok {
			return nil, fmt.Errorf("--binding names connector %q, which the topology does not declare", name)
		}
		if !slices.Contains(fixtures, binding) {
			return nil, fmt.Errorf("connector %s uses unsupported %s %q; available %ss: %s", name, valueLabel, binding, valueLabel, strings.Join(fixtures, ", "))
		}
	}

	choices := make(map[string]string, len(facts.Model.Connectors))
	var missing []string
	for _, connector := range facts.Model.Connectors {
		binding := explicit[connector.Name]
		if binding == "" && opts.Selector != nil {
			binding, err = selectConnectorBinding(ctx, opts.Selector, connector, fixtures, target)
			if err != nil {
				return nil, fmt.Errorf("select %s binding for connector %s: %w", strings.ToLower(target), connector.Name, err)
			}
		}
		if binding == "" {
			missing = append(missing, connector.Name)
			continue
		}
		if !slices.Contains(fixtures, binding) {
			return nil, fmt.Errorf("connector %s uses unsupported %s %q; available %ss: %s",
				connector.Name, valueLabel, binding, valueLabel, strings.Join(fixtures, ", "))
		}
		choices[connector.Name] = binding
	}
	if len(missing) > 0 {
		return nil, fmt.Errorf("%s bindings are required for connectors: %s\npass one '--binding <connector>=<%s>' for each; available %ss: %s",
			strings.ToLower(target), strings.Join(missing, ", "), valueLabel, valueLabel, strings.Join(fixtures, ", "))
	}
	return choices, nil
}

func bindChoicesToEnvironments(choices map[string]string, environments []string) map[string]map[string]string {
	resolved := make(map[string]map[string]string, len(choices))
	for connector, binding := range choices {
		perEnvironment := make(map[string]string, len(environments))
		for _, environment := range environments {
			perEnvironment[environment] = binding
		}
		resolved[connector] = perEnvironment
	}
	return resolved
}

func parseConnectorBindingArgs(args []string) (map[string]string, error) {
	bindings := make(map[string]string, len(args))
	for _, arg := range args {
		name, fixture, ok := strings.Cut(arg, "=")
		name, fixture = strings.TrimSpace(name), strings.TrimSpace(fixture)
		if !ok || name == "" || fixture == "" {
			return nil, fmt.Errorf("invalid --binding %q; use --binding <connector>=<fixture>", arg)
		}
		if _, duplicate := bindings[name]; duplicate {
			return nil, fmt.Errorf("--binding specifies connector %s more than once", name)
		}
		bindings[name] = fixture
	}
	return bindings, nil
}

func selectConnectorBinding(ctx context.Context, selector interactive.Selector, connector ManifestConnector, fixtures []string, target string) (string, error) {
	options := make([]interactive.SelectOption, 0, len(fixtures))
	for _, fixture := range fixtures {
		options = append(options, interactive.SelectOption{
			Label: fixtureLabel(fixture),
			Value: fixture,
		})
	}
	return selector.Select(ctx, interactive.SelectRequest{
		Title:       strings.ToLower(target) + " binding for " + connector.Name,
		Description: connectorDescription(connector),
		Options:     options,
	})
}

func connectorDescription(connector ManifestConnector) string {
	var details []string
	if connector.ExternalSystem != "" {
		details = append(details, "external system "+connector.ExternalSystem)
	}
	if len(connector.AppIDs) > 0 {
		details = append(details, "used by "+strings.Join(connector.AppIDs, ", "))
	}
	if len(details) == 0 {
		return "choose this connector's binding kind"
	}
	return strings.Join(details, "; ")
}

func fixtureLabel(fixture string) string {
	description := map[string]string{
		"blob": "S3 object store",
		"file": "local directory",
		"http": "HTTP stub",
		"sftp": "SFTP server",
		"smb":  "SMB share",
	}[fixture]
	if description == "" {
		return fixture
	}
	return fixture + " — " + description
}

// emptyGitOpsBindings leaves connector types unset for reviewers to complete
// in the GitOps repository. Local fixture choices belong solely to render.
func emptyGitOpsBindings(opts manifestRunOptions, facts manifestFacts) map[string]map[string]string {
	for _, env := range facts.Environments {
		for _, connector := range facts.Model.Connectors {
			fmt.Fprintf(opts.Stderr, "note: connector %s has no binding for %s; its manifests keep the REPLACE-ME scaffold\n", connector.Name, env)
		}
	}
	return map[string]map[string]string{}
}

